def apply_interior_fill(grid, rects):
    """Fill interior of each rectangle with 8s"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]  # Deep copy

    for min_r, max_r, min_c, max_c, val in rects:
        # Interior: exclude border (1 cell thick)
        if max_r - min_r < 2 or max_c - min_c < 2:
            continue  # Too small to have an interior

        for rr in range(min_r + 1, max_r):
            for cc in range(min_c + 1, max_c):
                result[rr][cc] = 8

    return result

